// ============================================
// CONFIG - TODOS LOS PROCESOS
// Emite un item por cada proceso/carpeta a procesar.
// Conecta directamente con "📋 Listar PDFs en Backblaze".
// Para agregar/quitar procesos, solo edita este array.
// ============================================

const PROCESOS = [
  {
    proceso_nombre: 'Investigación',
    codigo_proceso:  'INV-01',
    audit_scope:     '2025',
    b2_prefix:       'Procesos UNIMINUTO/01_Investigación/'
  },
  {
    proceso_nombre: 'Proyección Social',
    codigo_proceso:  'PS-01',
    audit_scope:     '2025',
    b2_prefix:       'Procesos UNIMINUTO/02_Proyección_Social/'
  },
  {
    proceso_nombre: 'Docencia',
    codigo_proceso:  'DC-01',
    audit_scope:     '2025',
    b2_prefix:       'Procesos UNIMINUTO/03_Docencia/'
  },
  {
    proceso_nombre: 'Gestión Administrativa y Financiera',
    codigo_proceso:  'GAF-01',
    audit_scope:     '2025',
    b2_prefix:       'Procesos UNIMINUTO/Gestión Administrativa y Financiera/'
  },
  {
    proceso_nombre: 'Gestión de Mercadeo y Posicionamiento',
    codigo_proceso:  'GMP-01',
    audit_scope:     '2025',
    b2_prefix:       'Procesos UNIMINUTO/Gestión de Mercadeo y Posicionamiento/'
  }
];

console.log(`🚀 Iniciando ingesta de ${PROCESOS.length} procesos...`);
PROCESOS.forEach((p, i) => console.log(`  ${i+1}. ${p.proceso_nombre} → ${p.b2_prefix}`));

return PROCESOS.map(p => ({ json: p }));

// ============================================
// LISTAR PDFs EN BACKBLAZE B2
// Lee todos los archivos del prefijo (carpeta) configurado
// ============================================

const B2_KEY_ID  = $env.B2_KEY_ID;
const B2_APP_KEY = $env.B2_APP_KEY;
const B2_BUCKET  = $env.B2_BUCKET;       // ej: uniminuto-docs
const B2_REGION  = $env.B2_REGION;       // ej: us-west-004

// El Config node pasa: proceso_nombre, codigo_proceso, audit_scope, b2_prefix
const config     = $input.first().json;
const prefix     = config.b2_prefix || '';
const auditScope = config.audit_scope || '2025';

const crypto = require('crypto');

function sha256hex(data) {
  return crypto.createHash('sha256').update(data, 'utf8').digest('hex');
}
function hmacSha256(key, data) {
  return crypto.createHmac('sha256', key).update(data, 'utf8').digest();
}
function getSigningKey(secretKey, dateOnly, region, service) {
  const kDate    = hmacSha256('AWS4' + secretKey, dateOnly);
  const kRegion  = hmacSha256(kDate, region);
  const kService = hmacSha256(kRegion, service);
  return hmacSha256(kService, 'aws4_request');
}

const now       = new Date();
const dateStr   = now.toISOString().replace(/[:\-]|\.\d{3}/g, '').slice(0, 15) + 'Z';
const dateOnly  = dateStr.slice(0, 8);
const host      = `s3.${B2_REGION}.backblazeb2.com`;
const endpoint  = `https://${host}`;

// S3 ListObjectsV2
const queryString = 'list-type=2&prefix=' + encodeURIComponent(prefix).replace(/%2F/g, '/');
const payloadHash = sha256hex('');
const canonicalHeaders = `host:${host}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${dateStr}\n`;
const signedHeaders    = 'host;x-amz-content-sha256;x-amz-date';

const canonicalRequest = [
  'GET',
  `/${B2_BUCKET}`,
  queryString,
  canonicalHeaders,
  signedHeaders,
  payloadHash
].join('\n');

const credentialScope = `${dateOnly}/${B2_REGION}/s3/aws4_request`;
const stringToSign = [
  'AWS4-HMAC-SHA256',
  dateStr,
  credentialScope,
  sha256hex(canonicalRequest)
].join('\n');

const signingKey = getSigningKey(B2_APP_KEY, dateOnly, B2_REGION, 's3');
const signature  = crypto.createHmac('sha256', signingKey).update(stringToSign).digest('hex');
const authHeader = `AWS4-HMAC-SHA256 Credential=${B2_KEY_ID}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;

const response = await this.helpers.httpRequest({
  method: 'GET',
  url: `${endpoint}/${B2_BUCKET}?${queryString}`,
  headers: {
    'Host': host,
    'x-amz-date': dateStr,
    'x-amz-content-sha256': payloadHash,
    'Authorization': authHeader
  }
});

// Parsear XML de ListObjectsV2
const keys = [];
const matches = response.matchAll(/<Key>([^<]+\.pdf)<\/Key>/gi);
for (const m of matches) {
  keys.push(m[1]);
}

console.log(`📁 Encontrados ${keys.length} PDFs en prefijo "${prefix}"`);

// Detectar proceso/subproceso por nombre de archivo (misma lógica que antes)
return keys.map(fileKey => {
  const fileName = fileKey.toLowerCase();
  let proceso = 'Desconocido';
  let codigoProceso = 'N/A';

  if (fileName.includes('[inv')) { proceso = 'Investigación'; codigoProceso = 'INV-01'; }
  else if (fileName.includes('[ps')) { proceso = 'Proyección Social'; codigoProceso = 'PS-01'; }
  else if (fileName.includes('[dc')) { proceso = 'Docencia'; codigoProceso = 'DC-01'; }
  else if (fileName.includes('[gaf')) { proceso = 'Gestión Administrativa y Financiera'; codigoProceso = 'GAF-01'; }
  else if (fileName.includes('[gmp')) { proceso = 'Gestión de Mercadeo y Posicionamiento'; codigoProceso = 'GMP-01'; }

  const nameParts = fileKey.split('/');
  const name = nameParts[nameParts.length - 1];

  console.log(`📄 ${name} → ${proceso}`);

  return {
    json: {
      fileKey,
      name,
      proceso,
      codigo_proceso: codigoProceso,
      audit_scope: auditScope
    }
  };
});

// ============================================
// DESCARGAR PDF DESDE BACKBLAZE B2
// Recibe: $json.fileKey, $json.name
// ============================================

const B2_KEY_ID  = $env.B2_KEY_ID;
const B2_APP_KEY = $env.B2_APP_KEY;
const B2_BUCKET  = $env.B2_BUCKET;
const B2_REGION  = $env.B2_REGION;

const fileKey = $input.item.json.fileKey;
const name    = $input.item.json.name;

const crypto = require('crypto');

function sha256hex(data) {
  return crypto.createHash('sha256').update(data, 'utf8').digest('hex');
}
function hmacSha256(key, data) {
  return crypto.createHmac('sha256', key).update(data, 'utf8').digest();
}
function getSigningKey(secretKey, dateOnly, region, service) {
  const kDate    = hmacSha256('AWS4' + secretKey, dateOnly);
  const kRegion  = hmacSha256(kDate, region);
  const kService = hmacSha256(kRegion, service);
  return hmacSha256(kService, 'aws4_request');
}

const now      = new Date();
const dateStr  = now.toISOString().replace(/[:\-]|\.\d{3}/g, '').slice(0, 15) + 'Z';
const dateOnly = dateStr.slice(0, 8);
const host     = `s3.${B2_REGION}.backblazeb2.com`;

const payloadHash      = sha256hex('');
const canonicalUri     = `/${B2_BUCKET}/${fileKey}`;
const canonicalHeaders = `host:${host}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${dateStr}\n`;
const signedHeaders    = 'host;x-amz-content-sha256;x-amz-date';

const canonicalRequest = ['GET', canonicalUri, '', canonicalHeaders, signedHeaders, payloadHash].join('\n');
const credentialScope  = `${dateOnly}/${B2_REGION}/s3/aws4_request`;
const stringToSign     = ['AWS4-HMAC-SHA256', dateStr, credentialScope, sha256hex(canonicalRequest)].join('\n');

const signingKey = getSigningKey(B2_APP_KEY, dateOnly, B2_REGION, 's3');
const signature  = crypto.createHmac('sha256', signingKey).update(stringToSign).digest('hex');
const authHeader = `AWS4-HMAC-SHA256 Credential=${B2_KEY_ID}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;

console.log(`📥 Descargando: ${fileKey}`);

const response = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://${host}${canonicalUri}`,
  headers: {
    'Host': host,
    'x-amz-date': dateStr,
    'x-amz-content-sha256': payloadHash,
    'Authorization': authHeader
  },
  encoding: 'arraybuffer',
  returnFullResponse: true
});

if (response.statusCode !== 200) {
  throw new Error(`Error al descargar de B2: ${response.statusCode}`);
}

console.log(`✅ Descargado: ${name} (${response.body.byteLength} bytes)`);

return [{
  json: {
    ...$input.item.json
  },
  binary: {
    data: await this.helpers.prepareBinaryData(
      Buffer.from(response.body),
      name,
      'application/pdf'
    )
  }
}];

const fileName = ($input.item.json.name || '').toLowerCase();
const fileNameOriginal = $input.item.json.name || 'sin_nombre.pdf';

console.log(`\n========================================`);
console.log(`📄 Archivo recibido: "${fileNameOriginal}"`);
console.log(`📄 Nombre en lowercase: "${fileName}"`);
console.log(`========================================\n`);

if (!fileName) {
  throw new Error('El archivo no tiene nombre');
}

let subproceso = '';

// DOCUMENTOS GLOBALES (aplican a todos los procesos)
if (fileName.includes('[global]') || fileName.includes('[gbl]')) {
  subproceso = 'Global';
  console.log('✅ Detectado: Documento Global');
}

// INVESTIGACIÓN
else if (fileName.includes('[inv-if]')) {
  subproceso = 'Investigación Formativa';
  console.log('✅ Detectado: Investigación Formativa');
} else if (fileName.includes('[inv-idic]') || fileName.includes('[inv-i+d+i+c]')) {
  subproceso = 'I+D+I+C';
  console.log('✅ Detectado: I+D+I+C');
} else if (fileName.includes('[inv-ge]')) {
  subproceso = 'Gestión Editorial';
  console.log('✅ Detectado: Gestión Editorial');
} else if (fileName.includes('[inv-tct]')) {
  subproceso = 'Transferencia de Conocimiento y Tecnología';
  console.log('✅ Detectado: Transferencia de Conocimiento y Tecnología');
}

// PROYECCIÓN SOCIAL
else if (fileName.includes('[ps-ec]')) {
  subproceso = 'Educación Continua';
  console.log('✅ Detectado: Educación Continua');
} else if (fileName.includes('[ps-gem]')) {
  subproceso = 'Gestión de Empleabilidad';
  console.log('✅ Detectado: Gestión de Empleabilidad');
} else if (fileName.includes('[ps-ppl]')) {
  subproceso = 'Práctica Profesional';
  console.log('✅ Detectado: Práctica Profesional');
} else if (fileName.includes('[ps-prs]')) {
  subproceso = 'Práctica en Responsabilidad Social';
  console.log('✅ Detectado: Práctica en Responsabilidad Social');
} else if (fileName.includes('[ps-vlo]')) {
  subproceso = 'Voluntariado';
  console.log('✅ Detectado: Voluntariado');
} else if (fileName.includes('[ps-reng]')) {
  subproceso = 'Relacionamiento con Egresados y Egresados no Graduados';
  console.log('✅ Detectado: Relacionamiento con Egresados y Egresados no Graduados');
} else if (fileName.includes('[ps-art]')) {
  subproceso = 'Articulación';
  console.log('✅ Detectado: Articulación');
} else if (fileName.includes('[ps-gde]')) {
  subproceso = 'Gestión y Desarrollo del Emprendimiento';
  console.log('✅ Detectado: Gestión y Desarrollo del Emprendimiento');
} else if (fileName.includes('[ps]')) {
  subproceso = 'General de Proyección Social';
  console.log('✅ Detectado: General de Proyección Social');
}

// DOCENCIA
else if (fileName.includes('[dc-eae]')) {
  subproceso = 'Enseñanza, Aprendizaje y Evaluación';
  console.log('✅ Detectado: Enseñanza, Aprendizaje y Evaluación');
} else if (fileName.includes('[dc-ve]')) {
  subproceso = 'Vida Estudiantil';
  console.log('✅ Detectado: Vida Estudiantil');
} else if (fileName.includes('[dc-dcu]')) {
  subproceso = 'Desarrollo Curricular';
  console.log('✅ Detectado: Desarrollo Curricular');
}

// GESTIÓN ADMINISTRATIVA Y FINANCIERA
else if (fileName.includes('[gaf-ging]')) {
  subproceso = 'Gestión de Ingresos';
  console.log('✅ Detectado: Gestión de Ingresos');
} else if (fileName.includes('[gaf-pfp]')) {
  subproceso = 'Planeación Financiera y Presupuesto';
  console.log('✅ Detectado: Planeación Financiera y Presupuesto');
} else if (fileName.includes('[gaf-cfc]')) {
  subproceso = 'Contabilidad Financiera y Costeo';
  console.log('✅ Detectado: Contabilidad Financiera y Costeo');
} else if (fileName.includes('[gaf-aprv]')) {
  subproceso = 'Aprovisionamiento';
  console.log('✅ Detectado: Aprovisionamiento');
} else if (fileName.includes('[gaf-aat]')) {
  subproceso = 'Administración de Tesorería';
  console.log('✅ Detectado: Administración de Tesorería');
} else if (fileName.includes('[gaf-gdtl]')) {
  subproceso = 'Gestión Documental';
  console.log('✅ Detectado: Gestión Documental');
} else if (fileName.includes('[gaf-gaa]')) {
  subproceso = 'Gestión Académico Administrativo';
  console.log('✅ Detectado: Gestión Académico Administrativo');
} else if (fileName.includes('[gaf]')) {
  subproceso = 'General Administrativa y Financiera';
  console.log('✅ Detectado: General Administrativa y Financiera');
}

// GESTIÓN DE MERCADEO Y POSICIONAMIENTO
else if (fileName.includes('[gmp-imd]')) {
  subproceso = 'Investigación de Mercados';
  console.log('✅ Detectado: Investigación de Mercados');
} else if (fileName.includes('[gmp-cyv]')) {
  subproceso = 'Comercialización y Ventas';
  console.log('✅ Detectado: Comercialización y Ventas');
} else if (fileName.includes('[gmp]')) {
  subproceso = 'General de Mercadeo y Posicionamiento';
  console.log('✅ Detectado: General de Mercadeo y Posicionamiento');
} else {
  console.warn(`❌ NO SE DETECTÓ NINGÚN PREFIJO`);
}

// DETECTAR TIPO DE DOCUMENTO
let tipoDocumento = 'otro';
if (fileName.includes('caracterizacion') || fileName.includes('caracterización')) {
  tipoDocumento = 'caracterizacion';
} else if (fileName.includes('procedimiento')) {
  tipoDocumento = 'procedimiento';
} else if (fileName.includes('instructivo')) {
  tipoDocumento = 'instructivo';
} else if (fileName.includes('formato') || fileName.includes('form')) {
  tipoDocumento = 'formato';
} else if (fileName.includes('manual')) {
  tipoDocumento = 'manual';
} else if (fileName.includes('politica') || fileName.includes('política')) {
  tipoDocumento = 'politica';
}

const versionMatch = fileName.match(/v(\d+\.?\d*)/i);
const version = versionMatch ? versionMatch[1] : '1.0';

const fechaMatch = fileName.match(/(\d{4})[-_](\d{2})[-_](\d{2})/);
let fechaEmision = null;
if (fechaMatch) {
  fechaEmision = `${fechaMatch[1]}-${fechaMatch[2]}-${fechaMatch[3]}`;
}

const esGlobal = subproceso === 'Global';
const esGeneral = subproceso.includes('General');

console.log(`   └─ Subproceso: ${subproceso || '⚠️ SIN PREFIJO'}`);
console.log(`   └─ Tipo: ${tipoDocumento}`);
console.log(`   └─ Es general: ${esGeneral}\n`);

return {
  json: {
    ...($input.item.json),
    name: fileNameOriginal,
    subproceso: subproceso,
    es_general: esGeneral,
    es_global: esGlobal,
    tipo_documento: tipoDocumento,
    version_documento: version,
    fecha_emision: fechaEmision,
    nombre_documento_original: fileNameOriginal
  },
  binary: $input.item.binary
};

return {
  json: {
    ...($input.item.json),
    _metadata_backup: {
      id: $input.item.json.id,
      name: $input.item.json.name,
      mimeType: $input.item.json.mimeType,
      proceso: $input.item.json.proceso,
      codigo_proceso: $input.item.json.codigo_proceso,
      audit_scope: $input.item.json.audit_scope,
      subproceso: $input.item.json.subproceso,
      es_general: $input.item.json.es_general,
      es_global: $input.item.json.es_global,
      tipo_documento: $input.item.json.tipo_documento,
      nombre_documento_original: $input.item.json.nombre_documento_original,
      version_documento: $input.item.json.version_documento,
      fecha_emision: $input.item.json.fecha_emision
    }
  },
  binary: $input.item.binary
};

const textoExtraido = $input.item.json.data || $input.item.json.text;

// Buscar metadata del nodo "Guardar Metadata"
const guardarNode = $('Guardar Metadata').item.json;

console.log(`📄 Proceso: ${guardarNode.proceso || 'no encontrado'}`);

return {
  json: {
    data: textoExtraido,
    proceso: guardarNode.proceso,
    codigo_proceso: guardarNode.codigo_proceso,
    audit_scope: guardarNode.audit_scope,
    subproceso: guardarNode.subproceso,
    es_general: guardarNode.es_general,
    es_global: guardarNode.es_global,
    tipo_documento: guardarNode.tipo_documento,
    nombre_documento_original: guardarNode.nombre_documento_original,
    version_documento: guardarNode.version_documento,
    fecha_emision: guardarNode.fecha_emision,
    id: guardarNode.id,
    name: guardarNode.name,
    mimeType: guardarNode.mimeType
  }
};

// ============================================
// EXTRAER Y LIMPIAR TEXTO
// ============================================

let textContent = '';

if ($input.item.json.data && typeof $input.item.json.data === 'string') {
  textContent = $input.item.json.data;
} else if ($input.item.json.text) {
  textContent = $input.item.json.text;
} else {
  throw new Error('No se pudo encontrar el texto extraído');
}

if (!textContent || textContent.length < 100) {
  throw new Error(`Documento muy corto: ${textContent.length} caracteres`);
}

const cleanText = textContent
  .replace(/\r\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '')
  .trim();

console.log(`✅ Texto: ${cleanText.length} caracteres`);
console.log(`📄 Doc: ${$input.item.json.nombre_documento_original || 'sin nombre'}`);

// Obtener metadata del input (viene del nodo "Guardar Metadata")
return {
  json: {
    contenido_completo: cleanText,
    longitud_contenido: cleanText.length,

    // Estos campos vienen del nodo "Guardar Metadata"
    id: $input.item.json.id,
    name: $input.item.json.name,
    mimeType: $input.item.json.mimeType,
    proceso: $input.item.json.proceso,
    codigo_proceso: $input.item.json.codigo_proceso,
    audit_scope: $input.item.json.audit_scope,
    subproceso: $input.item.json.subproceso,
    es_general: $input.item.json.es_general,
    tipo_documento: $input.item.json.tipo_documento,
    nombre_documento_original: $input.item.json.nombre_documento_original,
    version_documento: $input.item.json.version_documento,
    fecha_emision: $input.item.json.fecha_emision
  }
};

// ============================================
// DIVIDIR EN CHUNKS - PROCESA TODOS LOS ITEMS
// ============================================

const allItems = $input.all();
const allChunks = [];

for (const item of allItems) {
  const texto = item.json.contenido_completo;

  if (!texto || texto.length < 100) {
    console.warn(`Saltando item sin contenido suficiente`);
    continue;
  }

  const proceso = item.json.proceso || 'Sin Proceso';
  const subproceso = item.json.subproceso || '';
  const esGeneral = item.json.es_general || false;
  const codigoProceso = item.json.codigo_proceso || '';
  const tipoDocumento = item.json.tipo_documento || 'otro';
  const nombreDocumento = item.json.nombre_documento_original || item.json.name || 'sin_nombre.pdf';
  const versionDocumento = item.json.version_documento || '1.0';
  const fechaEmision = item.json.fecha_emision || null;
  const organization = 'UNIMINUTO';
  const sede = 'Bogotá';
  const auditScope = item.json.audit_scope || '2025';
  const documentoIdDrive = item.json.id || '';

  const chunkSize = 800;
  const overlap = 150;

  function simpleHash(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash;
    }
    return Math.abs(hash).toString(16);
  }

  const paragraphs = texto.split(/\n\n+/);
  const chunks = [];

  let currentChunk = '';
  let chunkIndex = 0;

  for (const paragraph of paragraphs) {
    const trimmedParagraph = paragraph.trim();
    if (!trimmedParagraph) continue;

    if (currentChunk.length + trimmedParagraph.length > chunkSize && currentChunk.length > 0) {
      chunks.push({
        contenido: currentChunk.trim(),
        chunk_index: chunkIndex
      });

      currentChunk = currentChunk.slice(-overlap) + '\n\n' + trimmedParagraph;
      chunkIndex++;
    } else {
      currentChunk += (currentChunk ? '\n\n' : '') + trimmedParagraph;
    }
  }

  if (currentChunk.trim()) {
    chunks.push({
      contenido: currentChunk.trim(),
      chunk_index: chunkIndex
    });
  }

  const totalChunks = chunks.length;

  console.log(`📄 ${nombreDocumento}: ${totalChunks} chunks`);
  if (subproceso) {
    console.log(`   └─ Subproceso: ${subproceso}`);
  }

  // Agregar chunks de este documento al array total
  for (let idx = 0; idx < chunks.length; idx++) {
    allChunks.push({
      json: {
        contenido: chunks[idx].contenido,
        chunk_index: idx,
        total_chunks: totalChunks,
        proceso: proceso,
        subproceso: subproceso,
        es_general: esGeneral,
        codigo_proceso: codigoProceso,
        tipo_documento: tipoDocumento,
        nombre_documento: nombreDocumento,
        version_documento: versionDocumento,
        fecha_emision: fechaEmision,
        organization: organization,
        sede: sede,
        audit_scope: auditScope,
        vigente: true,
        estado: 'vigente',
        hash_contenido: simpleHash(chunks[idx].contenido),
        creado_por: 'sistema_ingesta',
        documento_id_drive: documentoIdDrive
      }
    });
  }
}

console.log(`\n✅ Total de chunks generados: ${allChunks.length}`);

return allChunks;

// ============================================
// GENERAR EMBEDDING + INSERTAR EN SUPABASE - JINA v3 (1024 dims)
// ============================================

const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_KEY = $env.SUPABASE_KEY;
const JINA_API_KEY = $env.JINA_API_KEY; // ✅ Variable de entorno

const item = $input.item.json;

// 1. Generar embedding con Jina
const embeddingResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.jina.ai/v1/embeddings',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${JINA_API_KEY}`
  },
  body: {
    input: [item.pageContent.substring(0, 8000)],
    model: 'jina-embeddings-v3',
    task: 'retrieval.passage',
    dimensions: 1024
  },
  json: true
});

const embedding = embeddingResponse.data[0].embedding;
const embeddingVector = '[' + embedding.join(',') + ']';

// 2. Insertar en Supabase
await this.helpers.httpRequest({
  method: 'POST',
  url: `${SUPABASE_URL}/rest/v1/procesos_uniminuto_duplicate`,
  headers: {
    'Content-Type': 'application/json',
    'apikey': SUPABASE_KEY,
    'Authorization': `Bearer ${SUPABASE_KEY}`,
    'Prefer': 'return=minimal'
  },
  body: {
    content: item.pageContent,
    contenido: item.pageContent,
    embedding: embeddingVector,
    metadata: item.metadata,
    proceso: item.metadata.proceso,
    subproceso: item.metadata.subproceso,
    es_general: item.metadata.es_general,
    es_global: item.metadata.es_global,
    codigo_proceso: item.metadata.codigo_proceso,
    tipo_documento: item.metadata.tipo_documento,
    nombre_documento: item.metadata.nombre_documento,
    version_documento: item.metadata.version_documento,
    organization: item.metadata.organization,
    sede: item.metadata.sede,
    audit_scope: item.metadata.audit_scope,
    vigente: item.metadata.vigente,
    estado: item.metadata.estado,
    chunk_index: item.metadata.chunk_index,
    total_chunks: item.metadata.total_chunks,
    hash_contenido: item.metadata.hash_contenido,
    creado_por: item.metadata.creado_por
  },
  json: true
});

return { 
  json: { 
    success: true,
    proceso: item.metadata.proceso,
    codigo_proceso: item.metadata.codigo_proceso,
    audit_scope: item.metadata.audit_scope,
    subproceso: item.metadata.subproceso,
    tipo_documento: item.metadata.tipo_documento,
    nombre_documento: item.metadata.nombre_documento,
    es_general: item.metadata.es_general
  } 
};

const allItems = $input.all();

if (allItems.length === 0) {
  throw new Error('No hay items para resumir');
}

const primerItem = allItems[0].json;

// Leer proceso del primer item
const proceso = primerItem.proceso || 'Desconocido';
const codigoProceso = primerItem.codigo_proceso || 'N/A';
const auditScope = primerItem.audit_scope || '2025';

const insertados = allItems.filter(item => item.json && item.json.success).length;

const porTipoDoc = {};
const porSubproceso = {};
const documentosUnicos = new Set();

allItems.forEach(item => {
  const tipo = item.json.tipo_documento || 'otro';
  const sub = item.json.subproceso || 'sin_subproceso';
  const doc = item.json.nombre_documento || '';

  porTipoDoc[tipo] = (porTipoDoc[tipo] || 0) + 1;
  porSubproceso[sub] = (porSubproceso[sub] || 0) + 1;

  if (doc) documentosUnicos.add(doc);
});

const tieneGenerales = allItems.some(item => item.json.es_general === true);

console.log(`\n📊 RESUMEN INGESTA PROCESO`);
console.log(`====================================`);
console.log(`📋 Proceso: ${proceso}`);
console.log(`🔖 Código: ${codigoProceso}`);
console.log(`📅 Audit Scope: ${auditScope}`);
console.log(`✅ Chunks insertados: ${insertados}/${allItems.length}`);
console.log(`📄 Documentos procesados: ${documentosUnicos.size}`);

console.log(`\n📊 Distribución por tipo:`);
Object.entries(porTipoDoc).forEach(([tipo, count]) => {
  console.log(`   ${tipo}: ${count} chunks`);
});

console.log(`\n📊 Distribución por subproceso:`);
Object.entries(porSubproceso).forEach(([sub, count]) => {
  console.log(`   ${sub}: ${count} chunks`);
});

if (tieneGenerales) {
  console.log(`\n⭐ Se incluyeron documentos generales del proceso`);
}

return [{
  json: {
    proceso: proceso,
    codigo_proceso: codigoProceso,
    audit_scope: auditScope,
    total_chunks: allItems.length,
    chunks_insertados: insertados,
    documentos_procesados: documentosUnicos.size,
    lista_documentos: Array.from(documentosUnicos),
    distribucion_tipos: porTipoDoc,
    distribucion_subprocesos: porSubproceso,
    tiene_documentos_generales: tieneGenerales,
    timestamp: new Date().toISOString()
  }
}];
